const payload = $input.first().json.body ?? $input.first().json;
const recipients = payload.recipients?.email ?? [];
const santri = payload.santri ?? {};
const orangTua = payload.orang_tua ?? {};
const alamat = payload.alamat ?? {};
const group = payload.group ?? {};
const ringkasan = payload.ringkasan?.baris ?? {};

function esc(value) {
  return String(value ?? '-').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
}

function groupNoticeFor(recipient) {
  const isAkhwat = group.kelas === 'akhwat';
  if (!isAkhwat) return group.aturan ?? 'Peserta didik putra masuk grup kelas ikhwan. Nomor WhatsApp bapak dan ibu diperbolehkan untuk masuk grup kelas ikhwan ini.';
  if (recipient.role === 'ibu') return group.aturan ?? 'Peserta didik putri masuk grup kelas akhwat. Hanya nomor WhatsApp ibu yang diperbolehkan untuk masuk grup kelas akhwat ini.';
  return 'Peserta didik putri masuk grup kelas akhwat. Link grup kelas akhwat hanya dikirim ke nomor WhatsApp/email ibu.';
}

function groupLinkFor(recipient) {
  if (group.kelas === 'akhwat' && recipient.role !== 'ibu') return '';
  return group.link ?? '';
}

const summaryRows = Object.entries(ringkasan)
  .map(([label, value]) => `<tr><td style="padding:7px 10px;border:1px solid #e5e7eb;font-weight:700;background:#f8fafc;">${esc(label)}</td><td style="padding:7px 10px;border:1px solid #e5e7eb;">${esc(value)}</td></tr>`)
  .join('');

const subject = `Ringkasan Pendataan SPSB - ${santri.nama_lengkap ?? ''}`;

return recipients.map((recipient) => {
  const groupLink = groupLinkFor(recipient);
  const groupLinkText = groupLink
    ? `<p>Link grup kelas: <a href="${esc(groupLink)}">${esc(groupLink)}</a></p>`
    : (group.kelas === 'akhwat' && recipient.role !== 'ibu' ? '' : '<p>Link grup kelas belum tersedia. Admin akan mengirimkan link menyusul.</p>');
  const html = `
<div style="font-family:Arial,sans-serif;color:#0f172a;line-height:1.55;">
  <h2 style="margin:0 0 12px;color:#047857;">Pendataan SPSB Berhasil Diterima</h2>
  <p>Assalamu'alaikum Bapak/Ibu,</p>
  <p>Data pendataan ananda <strong>${esc(santri.nama_lengkap)}</strong> telah masuk ke sistem SPSB.</p>
  <table style="border-collapse:collapse;width:100%;max-width:720px;margin:16px 0;font-size:14px;">
    ${summaryRows}
    <tr><td style="padding:7px 10px;border:1px solid #e5e7eb;font-weight:700;background:#f8fafc;">Nama Ayah</td><td style="padding:7px 10px;border:1px solid #e5e7eb;">${esc(orangTua.ayah?.nama)}</td></tr>
    <tr><td style="padding:7px 10px;border:1px solid #e5e7eb;font-weight:700;background:#f8fafc;">Nama Ibu</td><td style="padding:7px 10px;border:1px solid #e5e7eb;">${esc(orangTua.ibu?.nama)}</td></tr>
    ${alamat.alamat_lengkap ? `<tr><td style="padding:7px 10px;border:1px solid #e5e7eb;font-weight:700;background:#f8fafc;">Alamat</td><td style="padding:7px 10px;border:1px solid #e5e7eb;">${esc(alamat.alamat_lengkap)}, ${esc(alamat.kelurahan_desa)}, ${esc(alamat.kecamatan)}</td></tr>` : ''}
  </table>
  <p><strong>Informasi grup kelas:</strong><br>${esc(groupNoticeFor(recipient))}</p>
  ${groupLinkText}
  <p>Dokumen pendataan dapat dibuka melalui tautan berikut:<br><a href="${esc(payload.links?.cetak)}">${esc(payload.links?.cetak)}</a></p>
  <p style="margin-top:20px;">Jazakumullah khairan,<br>Panitia SPSB</p>
</div>`;

  return {
    json: {
      to_email: recipient.email,
      to_name: recipient.name,
      subject,
      html,
      event: 'pendataan_baru',
      payload
    }
  };
});
